// Run only when intentionally regenerating the checked-in Bubblewrap project.
// Application source is generated by Google's pinned @bubblewrap/core, then
// hardened deterministically here. No remote manifest or secrets are required.
import fs from 'node:fs/promises';
import path from 'node:path';
import http from 'node:http';
import { fileURLToPath } from 'node:url';
import { TwaGenerator, TwaManifest, ConsoleLog } from '@bubblewrap/core';

const android = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const root = path.dirname(android);
const release = JSON.parse(await fs.readFile(path.join(android, 'release.json'), 'utf8'));
const server = http.createServer(async (req, res) => {
  const files = { '/icon.png': 'icon-512.png', '/maskable.png': 'maskable-512.png' };
  const name = files[req.url];
  if (!name) { res.writeHead(404).end(); return; }
  res.setHeader('Content-Type', 'image/png');
  res.end(await fs.readFile(path.join(root, 'public/pwa', name)));
});
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
try {
  const base = `http://127.0.0.1:${server.address().port}`;
  const data = {
    packageId: release.applicationId, host: 'www.modelssuite.com',
    name: 'Models Suite', launcherName: 'Models Suite', display: 'standalone',
    themeColor: '#05070a', themeColorDark: '#05070a', navigationColor: '#05070a',
    navigationColorDark: '#05070a', backgroundColor: '#05070a',
    enableNotifications: false, startUrl: '/chat',
    iconUrl: `${base}/icon.png`, maskableIconUrl: `${base}/maskable.png`,
    splashScreenFadeOutDuration: 200,
    signingKey: { path: 'PRIVATE_KEY_OUTSIDE_REPOSITORY', alias: 'models-suite-release' },
    appVersion: release.versionName, appVersionCode: release.versionCode,
    shortcuts: [], generatorApp: '@bubblewrap/core 1.27.0',
    fallbackType: 'customtabs', features: {}, alphaDependencies: { enabled: false },
    enableSiteSettingsShortcut: true, isChromeOSOnly: false, isMetaQuest: false,
    fullScopeUrl: 'https://www.modelssuite.com/', minSdkVersion: release.minSdk,
    orientation: 'default', fingerprints: [], additionalTrustedOrigins: [], retainedBundles: [],
  };
  const manifest = new TwaManifest(data);
  await new TwaGenerator().createTwaProject(android, manifest, new ConsoleLog('Models Suite'));
  await fs.writeFile(path.join(android, 'twa-manifest.json'), JSON.stringify({ ...data,
    iconUrl: 'https://www.modelssuite.com/pwa/icon-512.png',
    maskableIconUrl: 'https://www.modelssuite.com/pwa/maskable-512.png',
    webManifestUrl: 'https://www.modelssuite.com/manifest.webmanifest',
  }, null, 2) + '\n');
  let top = await fs.readFile(path.join(android, 'build.gradle'), 'utf8');
  top = top.replaceAll('jcenter()', 'mavenCentral()').replace('gradle:8.9.1', 'gradle:8.10.1');
  await fs.writeFile(path.join(android, 'build.gradle'), top);
  let app = await fs.readFile(path.join(android, 'app/build.gradle'), 'utf8');
  app = app.replace(/compileSdkVersion \d+/, 'compileSdkVersion 36').replace(/targetSdkVersion \d+/, 'targetSdkVersion 36');
  app = app.replace(/versionCode \d+/, 'versionCode releaseConfig.versionCode').replace(/versionName [^\r\n]+/, 'versionName releaseConfig.versionName');
  app = app.replace("id 'com.android.application'\n}", "id 'com.android.application'\n}\n\ndef releaseConfig = new groovy.json.JsonSlurper().parse(rootProject.file('release.json'))");
  app = app.replace('compileSdkVersion 36', 'compileSdkVersion releaseConfig.compileSdk');
  app = app.replace('android {', "android {\n    buildToolsVersion '36.0.0'");
  app = app.replace('targetSdkVersion 36', 'targetSdkVersion releaseConfig.targetSdk');
  app = app.replace(/minSdkVersion \d+/, 'minSdkVersion releaseConfig.minSdk');
  // Fail closed: release tasks never produce unsigned artifacts accidentally.
  app = app.replace('    buildTypes {', `    signingConfigs {
        release {
            def keyPath = System.getenv('MODELS_ANDROID_KEYSTORE')
            if (keyPath) {
                storeFile file(keyPath)
                storePassword System.getenv('MODELS_ANDROID_STORE_PASSWORD')
                keyAlias System.getenv('MODELS_ANDROID_KEY_ALIAS') ?: 'models-suite-release'
                keyPassword System.getenv('MODELS_ANDROID_KEY_PASSWORD')
            }
        }
    }
    buildTypes {`).replace('minifyEnabled true', 'minifyEnabled true\n            signingConfig signingConfigs.release');
  app += `\ngradle.taskGraph.whenReady { graph ->
    if (graph.allTasks.any { it.name.toLowerCase().contains('release') }) {
        ['MODELS_ANDROID_KEYSTORE','MODELS_ANDROID_STORE_PASSWORD','MODELS_ANDROID_KEY_PASSWORD'].each { key ->
            if (!System.getenv(key)) throw new GradleException('Release signing requires ' + key)
        }
    }
}\n`;
  // Bubblewrap's default helper is retained and pinned (no '+' versions).
  app = app.replace(/androidbrowserhelper:([\d.]+)\+?/g, 'androidbrowserhelper:$1');
  await fs.writeFile(path.join(android, 'app/build.gradle'), app);
  let xml = await fs.readFile(path.join(android, 'app/src/main/AndroidManifest.xml'), 'utf8');
  xml = xml.replace('android:allowBackup="true"', 'android:allowBackup="false"');
  xml = xml.replace('<application', '<application android:usesCleartextTraffic="false"');
  xml = xml.replace('<activity android:name="LauncherActivity"', '<activity android:name="LauncherActivity" android:windowSoftInputMode="adjustResize"');
  await fs.writeFile(path.join(android, 'app/src/main/AndroidManifest.xml'), xml);
  let wrapper = await fs.readFile(path.join(android,'gradle/wrapper/gradle-wrapper.properties'), 'utf8');
  wrapper = wrapper.replace('networkTimeout=10000','networkTimeout=120000');
  const checksum = (await (await fetch('https://services.gradle.org/distributions/gradle-8.11.1-bin.zip.sha256')).text()).trim();
  if (!/^[a-f0-9]{64}$/.test(checksum)) throw new Error('Invalid Gradle checksum');
  await fs.writeFile(path.join(android,'gradle/wrapper/gradle-wrapper.properties'), wrapper + `\ndistributionSha256Sum=${checksum}\n`);
  console.log('Bubblewrap Android project generated with API 36 and external release signing.');
} finally { server.close(); }
